import { readdir, writeFile } from "node:fs/promises";
import { join } from "node:path";

const domain = "https://aesop.elvish.nz";
const output = "build/client";

// Read the HTML files generated by React Router.
const files = await readdir(output);

// Include only the actual pages of the website.
const pages = files
  .filter(file =>
    file === "index.html" ||
    file === "about.html" ||
    /^tale-\d+\.html$/.test(file)
  )
  .sort((a, b) => {
    if (a === "index.html") return -1;
    if (b === "index.html") return 1;
    return a.localeCompare(b, undefined, { numeric: true });
  });

// Generate the sitemap.
const urls = pages.map(file => {
  const path = file === "index.html" ? "/" : `/${file}`;
  const url = new URL(path, domain).href;

  return `  <url>
    <loc>${url}</loc>
  </url>`;
});

const sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.join("\n")}
</urlset>
`;

await writeFile(
  join(output, "sitemap.xml"),
  sitemap,
  "utf8"
);

console.log(`Generated sitemap.xml with ${pages.length} URLs`);
